  const posted = (await call('POST', '/groups/trip/expenses', expenseBody({ description: 'Taxi', amount: 12.5 }))).body
  assert.deepEqual(imported.split, ['Ann', 'Ben', 'Cara'])
  assert.deepEqual({ ...imported, id: 0 }, { ...posted, id: 0 })
  assert.deepEqual(Object.keys(imported), Object.keys(posted))
}))

test('import: balances follow the group member order and include earlier records', () =>
  withTrip(async ({ call }) => {
    const hotel = await call('POST', '/groups/trip/expenses', expenseBody())
    assert.equal(hotel.status, 201)
    const r = await importInto(call, { entries: [expense({ description: 'Taxi', payer: 'Ben', amount: 12 }), payment()] })
    assert.equal(r.status, 201)
    assert.deepEqual(Object.keys(r.body.balances), ['Cara', 'Ann', 'Ben'])
    assert.deepEqual(r.body.balances, { Cara: -34, Ann: 30, Ben: 4 })
    assert.deepEqual(r.body.balances, (await call('GET', '/groups/trip/balances')).body.balances)
  }, { id: 'trip', name: 'Ski trip', members: ['Cara', 'Ann', 'Ben'] }))

test('import: a remainder goes to the first people in split', () => withTrip(async ({ call }) => {
  const entry = expense({ description: 'Dinner', amount: 10, split: ['Ann', 'Ben', 'Cara'] })
  const r = await importInto(call, { entries: [entry] })
  assert.equal(r.status, 201)
  assert.deepEqual(r.body.expenses[0].shares, { Ann: 3.34, Ben: 3.33, Cara: 3.33 })
  assert.deepEqual(r.body.balances, { Ann: 6.66, Ben: -3.33, Cara: -3.33 })
}))

test('import: a 201 reply is application/json', () => withTrip(async ({ call }) => {
